export function zoneOutline(place){
 const scale=600,cos=Math.cos(place.latitude*Math.PI/180);let path='';
 for(const run of coast){if(!run.some(([x,y])=>Math.abs(x-place.longitude)<1.5&&Math.abs(y-place.latitude)<1.5))continue;path+=run.map(([x,y],i)=>(i?'L':'M')+(180+(x-place.longitude)*cos*scale).toFixed(1)+','+(260-(y-place.latitude)*scale).toFixed(1)).join('')}
 return `<svg viewBox="0 0 360 520" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path d="${path}" fill="none" stroke="#466277" stroke-width="2"/><circle cx="180" cy="260" r="5" fill="#8ab4ce"/></svg>`;
}
